#!/bin/bash
sed -i -z 's/var contentToSave = text.*if (!contentToSave.isNullOrBlank()) {/var contentToSave = text\n                                    if (uri != null) {\n                                        try {\n                                            this@OverlayService.contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION)\n                                            contentToSave = uri.toString()\n                                        } catch (e: Exception) {\n                                            contentToSave = uri.toString()\n                                        }\n                                    }\n                                    if (!contentToSave.isNullOrBlank()) {/g' /app/applet/app/src/main/java/com/example/overlay/OverlayService.kt
